import React, { useState } from 'react';
import { API } from './config';
import './Home.css';   // ✅ import CSS file

function Home() {
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [challans, setChallans] = useState([]);

  async function searchChallans(e) {
    e.preventDefault();
    if (!vehicleNumber) return alert('Enter vehicle number');
    try {
      const res = await fetch(API + '/challan/vehicle/' + vehicleNumber);
      const data = await res.json();
      setChallans(data);
    } catch (err) {
      console.error(err);
      alert('Error fetching challans');
    }
  }

  return (
    <div className="home-container">
      <h2>Traffic Challan System</h2>
      <p>Search challans by vehicle number</p>

      {/* Search Form */}
      <form onSubmit={searchChallans} className="search-form">
        <input
          type="text"
          placeholder="Enter Vehicle Number"
          value={vehicleNumber}
          onChange={e => setVehicleNumber(e.target.value)}
        />
        <button type="submit">Search</button>
      </form>

      {/* Challans Table */}
      {challans.length > 0 && (
        <div className="results">
          <h3>Results for {vehicleNumber}</h3>
          <table className="challans-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Vehicle</th>
                <th>Cause</th>
                <th>Fine</th>
                <th>Status</th>
                <th>Issue Date</th>
              </tr>
            </thead>
            <tbody>
              {challans.map((c, i) => (
                <tr key={c._id}>
                  <td>{i + 1}</td>
                  <td>{c.vehicleNumber}</td>
                  <td>{c.cause}</td>
                  <td>{c.fine}</td>
                  <td>{c.status}</td>
                  <td>{c.issueDate}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

export default Home;
